/**
 * M2 capture layer: observes Node-RED's send/complete/error events for a
 * single node invocation without letting the message actually route locally.
 *
 * No Temporal involved here. Pure @node-red/util `hooks` usage plus a
 * reversible, INSTANCE-SCOPED (not prototype-wide) patch of `node.error` for
 * the exact duration of a single `around()` call - the only place a
 * synchronously-thrown node error surfaces, since it bypasses the
 * `onComplete` hook entirely (see Node.js `_emitInput`'s catch block).
 *
 * Patching the shared `Node.prototype.error` for the whole process lifetime
 * was tried and rejected: it is a global mutable side effect that survives
 * beyond a single invocation and can leak across unrelated node executions
 * (e.g. in a shared test process) if install()/uninstall() timing is ever
 * imperfect. Patching only the specific node instance, refcounted so two
 * concurrent invocations on the SAME node share one patch safely (see
 * "Correlation" below), and always restored via every exit path
 * (resolve/reject/timeout), keeps the blast radius to exactly the set of
 * invocations currently in flight against that one node.
 *
 * --- Correlation (issue #12 finding 1) ---
 * Activity invocations used to be correlated by the string key
 * `${node.id}::${msg._msgid}`. `_msgid` is Node-RED message identity, not
 * Temporal Activity-invocation identity: two concurrent Activities hitting
 * the SAME node with the SAME `_msgid` (a legitimate possibility once
 * autonomous source ingress (#9) can start multiple concurrent Workflow
 * Executions) would collide in `_pending`, cross-contaminating sends,
 * completion and errors.
 *
 * Fix: `around()` runs `fn()` inside a Node.js `AsyncLocalStorage` context
 * carrying a dedicated `invocationId`, independent of `_msgid`. That context
 * automatically follows the node's ENTIRE synchronous-and-asynchronous
 * continuation chain (promises, timers, callbacks), so `preRoute`,
 * `onComplete` and the patched `node.error` can all read
 * `this._als.getStore()` to recover exactly which `around()` invocation
 * they belong to - without depending on `msg` identity or `_msgid` at all.
 * This survives the common node-author pattern of constructing brand-new
 * message objects to `send()` (e.g. `send({ payload: 1, _msgid: msg._msgid })`),
 * which a `msg`-object-identity-based correlation scheme would miss.
 *
 * --- msg-identity fallback (issue #31) ---
 * ALS alone breaks when a node defers/batches a previous invocation's
 * `done()` call and fires it from within a LATER invocation's own call
 * stack (Node-RED's real `join` node in custom/count mode does exactly
 * this). `around()` also stashes the exact `msg` object it was called
 * with on the pending entry; `_onComplete()` first tries the ALS-derived
 * invocationId but only trusts it if that entry's `msg` matches
 * `completeEvent.msg` (strict identity - the same object Node.js's
 * `_emitInput`/`_complete` close over per invocation). On a mismatch (or
 * no ALS store), it falls back to scanning `_pending` for the entry with
 * the same `nodeId` and matching `msg`, correctly attributing the
 * `onComplete` to its true owning invocation instead of whichever one
 * happens to be active on the ALS stack.
 */

"use strict";

const { AsyncLocalStorage } = require("async_hooks");
const { util: redUtil } = require("@node-red/util");

const DEFAULT_TIMEOUT_MS = 5000;

class Capture {
    constructor(opts) {
        opts = opts || {};
        this.timeoutMs = opts.timeoutMs || DEFAULT_TIMEOUT_MS;
        this._onIngress = typeof opts.onIngress === "function" ? opts.onIngress : null;
        this._pending = new Map();
        this._als = new AsyncLocalStorage();
        this._invocationSeq = 0;
        this._errorPatches = new Map();
        // Finding 3 (issue #12): grouping of autonomous ingress sends into
        // one logical emission. See _onSend()/_onIngressPreRoute() below.
        this._ingressGroups = new Map();
        this._sendGroupOf = new WeakMap();
        this._sendGroupExpected = new Map();
        this._sendSeq = 0;
        this._installed = false;
        this._RED = null;

        this._onSend = this._onSend.bind(this);
        this._onPreRoute = this._onPreRoute.bind(this);
        this._onComplete = this._onComplete.bind(this);
    }

    /** Register onSend/preRoute/onComplete hooks against a live RED runtime. */
    install(RED) {
        if (this._installed) {
            return;
        }
        this._RED = RED;
        RED.hooks.add("onSend.temporal", this._onSend);
        RED.hooks.add("preRoute.temporal", this._onPreRoute);
        RED.hooks.add("onComplete.temporal", this._onComplete);
        this._installed = true;
    }

    /** Undo install(): remove hooks, clear any still-pending timers/patches. */
    uninstall() {
        if (!this._installed) {
            return;
        }
        this._RED.hooks.remove("onSend.temporal");
        this._RED.hooks.remove("preRoute.temporal");
        this._RED.hooks.remove("onComplete.temporal");
        this._pending.forEach((entry) => clearTimeout(entry.timer));
        this._pending.clear();
        this._ingressGroups.clear();
        this._sendGroupExpected.clear();
        // Defensive: restore any node.error patches still active (should
        // normally already be empty - every around() exit path unpatches).
        this._errorPatches.forEach((entry, node) => {
            if (Object.prototype.hasOwnProperty.call(node, "error")) {
                delete node.error;
            }
        });
        this._errorPatches.clear();
        this._installed = false;
        this._RED = null;
    }

    /**
     * Run `fn` (which must trigger `node` to receive `msg`) and resolve once
     * that invocation is done. Correlation uses a dedicated `invocationId`
     * carried by an `AsyncLocalStorage` context around the `fn()` call (see
     * class doc "Correlation") - NOT `node.id + msg._msgid`, which can
     * collide across two concurrent invocations sharing the same `_msgid`.
     *
     * `node.error` is patched as an own-property on this one node instance,
     * refcounted across any concurrently in-flight invocations on that same
     * node, and removed once the last of them settles.
     */
    around(node, msg, fn) {
        if (!msg._msgid) {
            msg._msgid = `cap-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
        }
        const nodeId = node.id;
        const invocationId = `${nodeId}#${++this._invocationSeq}`;
        this._patchNodeError(node);

        const restore = () => {
            this._unpatchNodeError(node);
        };
        return new Promise((resolve, reject) => {
            const timer = setTimeout(() => {
                this._pending.delete(invocationId);
                restore();
                reject({ nodeId, error: new Error(`capture timed out after ${this.timeoutMs}ms`), timeout: true });
            }, this.timeoutMs);
            this._pending.set(invocationId, {
                nodeId,
                msg,
                sends: [],
                flow: node._flow,
                resolve: (v) => { restore(); resolve(v); },
                reject: (v) => { restore(); reject(v); },
                timer
            });
            this._als.run(invocationId, () => {
                try {
                    fn();
                } catch (err) {
                    this._settleError(invocationId, nodeId, err);
                }
            });
        });
    }

    /**
     * Refcounted, shared-per-node `node.error` patch: two concurrent
     * `around()` invocations on the SAME node instance must not clobber
     * each other's patch (a naive per-invocation patch/delete would let the
     * invocation that settles first delete the property out from under the
     * other still-pending invocation). The shared patched function reads
     * `this._als.getStore()` to route the error to only its owning
     * invocation.
     */
    _patchNodeError(node) {
        let entry = this._errorPatches.get(node);
        if (!entry) {
            const origError = node.error;
            const self = this;
            node.error = function patchedError(logMessage) {
                // issue #13: call Node-RED's REAL error handling (which
                // synchronously routes the message to any wired Catch node
                // - Flow.js's own handleError, unmodified upstream code)
                // BEFORE settling our own pending invocation. A Catch
                // node's own `send()` fires `preRoute` synchronously inside
                // this call and is recorded into `pending.sends` (same
                // ALS invocationId) the normal way; settling first would
                // delete `pending` out from under that still-to-come
                // routing and silently drop it. This is capture-layer
                // ordering, not a Catch-specific reimplementation - Catch's
                // own routing semantics are still 100% Node-RED's.
                const result = origError.apply(node, arguments);
                self._onNodeError(logMessage);
                return result;
            };
            entry = { refcount: 0 };
            this._errorPatches.set(node, entry);
        }
        entry.refcount++;
    }

    _unpatchNodeError(node) {
        const entry = this._errorPatches.get(node);
        if (!entry) {
            return;
        }
        entry.refcount--;
        if (entry.refcount <= 0) {
            if (Object.prototype.hasOwnProperty.call(node, "error")) {
                delete node.error;
            }
            this._errorPatches.delete(node);
        }
    }

    _onSend(sendEvents, done) {
        // Only bother tagging sends when ingress grouping is actually
        // configured - Activity-owned invocations are already correlated
        // via the AsyncLocalStorage context and never consult these maps.
        if (this._onIngress) {
            const groupId = `send-${++this._sendSeq}`;
            this._sendGroupExpected.set(groupId, sendEvents.length);
            for (const sendEvent of sendEvents) {
                this._sendGroupOf.set(sendEvent, groupId);
            }
        }
        done();
    }

    /**
     * issue #23: a subflow instance's OWN internal hops (e.g. its "in" wire
     * to the first internal node, or one internal node's wire to the next)
     * are Node-RED implementation details, not Activity-worthy sends - the
     * whole point of `around()` invoking a subflow instance node is that
     * Node-RED routes internally through it exactly as it would outside of
     * Capture. But `preRoute` fires for EVERY hop while an invocation is in
     * flight, internal or not, and `sendEvent.destination.node` is not yet
     * populated at this point (Flow.js's `handlePreRoute` resolves it only
     * AFTER the `preRoute` hook settles) - so the destination must be
     * looked up explicitly. `RED.nodes.getNode()` (the `RED` passed to
     * `install()`) is not always the full runtime - callers may pass just
     * `@node-red/util` (which only exposes `hooks`) - so the lookup instead
     * uses `node._flow` (the live `Flow` instance every Node-RED node
     * instance carries - `Node.js` assigns it in its constructor), captured
     * once per invocation in `around()` and stashed on `pending.flow`.
     * `flow.getNode(id)` is the exact same lookup Flow.js's own
     * `handlePreRoute` uses to populate `sendEvent.destination.node` right
     * after this hook returns (`Flow.js:810`), so this mirrors upstream
     * behavior rather than inventing a new lookup path.
     *
     * Node-RED clones a subflow instance's internal nodes per-instance at
     * deploy time with `node.z` rewritten to the subflow INSTANCE's own id
     * (confirmed by reading `@node-red/runtime/lib/flows/Subflow.js`'s
     * `createNodeInSubflow()`, and empirically by booting the subflow
     * fixture: an internal node's `.z` equals its owning instance's `.id`).
     * `pending.nodeId` is the id of the node Capture's `around()` is
     * currently invoking - i.e. the subflow instance itself when this hop
     * originates from inside it. So "destination.z === pending.nodeId"
     * exactly discriminates "hop stays inside the subflow instance
     * currently being invoked" from "hop leaves the subflow instance" (a
     * real Activity-worthy send, still captured and suppressed as before).
     */
    _onPreRoute(sendEvent, done) {
        const invocationId = this._als.getStore();
        const pending = invocationId ? this._pending.get(invocationId) : undefined;
        if (pending) {
            const destNode = pending.flow ? pending.flow.getNode(sendEvent.destination.id) : undefined;
            if (destNode && destNode.z === pending.nodeId) {
                done();
                return;
            }
            // issue #31: Node-RED's OWN routing only clones `sendEvent.msg`
            // for a fan-out AFTER this hook returns (Flow.js's
            // `handlePreRoute`, `sendEvent.cloneMessage` flag, unmodified
            // upstream code at Flow.js:812-813) - and only when delivery
            // actually proceeds (`err !== false`). Capture always suppresses
            // local delivery (`done(false)` below), so that upstream clone
            // never runs; without replicating it here, two fanned-out
            // destinations of the SAME node.send() call (e.g. n1 -> n2 and
            // n1 -> n3) would carry the exact same `msg` OBJECT into their
            // respective downstream Activity invocations. That collapses
            // the msg-identity correlation `_onComplete()`/`_resolveInvocationId()`
            // rely on (two concurrently-pending invocations of the SAME
            // downstream node, e.g. join1, would then have indistinguishable
            // `msg` references). Cloning here - exactly mirroring upstream's
            // own `cloneMessage` flag - keeps each captured send's `msg`
            // as distinct an object as it would have been under normal
            // Node-RED routing.
            const capturedMsg = sendEvent.cloneMessage ? redUtil.cloneMessage(sendEvent.msg) : sendEvent.msg;
            pending.sends.push({ port: sendEvent.source.port, destinationId: sendEvent.destination.id, msg: capturedMsg });
        } else {
            this._onIngressPreRoute(sendEvent);
        }
        done(false);
    }

    /**
     * A preRoute event with no matching pending Activity (no active
     * AsyncLocalStorage invocation context) is an autonomous source send
     * (e.g. a scheduled Inject firing on its own).
     *
     * Grouping boundary (issue #12 finding 3): Node-RED's `onSend` hook
     * fires exactly once per logical `node.send()` call, with the FULL
     * array of `SendEvent`s that call is about to route
     * (`Flow.js`'s `handleOnSend`/`send()` - "onSend - passed an array of
     * SendEvent objects"), strictly BEFORE `preRoute` fires once per
     * individual SendEvent in that array. `_onSend()` above tags every
     * SendEvent in one such array with the same `groupId` and records the
     * array's exact length. Grouping preRoute events by that `groupId` and
     * flushing the instant the group has received exactly that many
     * `preRoute` events is therefore tied to one exact `node.send()` call
     * boundary - not a `setImmediate` timing window - so two synchronous
     * `node.send(msg); node.send(msg);` calls (same `_msgid`) get two
     * distinct `groupId`s and are never collapsed into one ingress event.
     */
    _onIngressPreRoute(sendEvent) {
        if (!this._onIngress) {
            return;
        }
        const msg = sendEvent.msg;
        const groupId = this._sendGroupOf.get(sendEvent);
        const send = { port: sendEvent.source.port, destinationId: sendEvent.destination.id, msg };
        let group = this._ingressGroups.get(groupId);
        if (!group) {
            group = { sourceNodeId: sendEvent.source.id, msg, sends: [] };
            this._ingressGroups.set(groupId, group);
        }
        group.sends.push(send);

        const expected = this._sendGroupExpected.get(groupId);
        if (expected !== undefined && group.sends.length >= expected) {
            this._ingressGroups.delete(groupId);
            this._sendGroupExpected.delete(groupId);
            this._onIngress({ sourceNodeId: group.sourceNodeId, msg: group.msg, sends: group.sends });
        }
    }

    /**
     * issue #31: resolve the TRUE owning invocation for a completeEvent.
     * The ALS-derived invocationId is trusted only if its pending entry's
     * `msg` matches `completeEvent.msg` (strict identity). Otherwise, scan
     * `_pending` for the entry belonging to the same node whose `msg`
     * matches - this recovers the correct (earlier) invocation when a node
     * defers and fires an earlier invocation's `done()` from within a
     * later invocation's own call stack (e.g. Node-RED's real `join` node,
     * custom/count mode).
     */
    _resolveInvocationId(completeEvent) {
        const alsInvocationId = this._als.getStore();
        if (alsInvocationId) {
            const alsPending = this._pending.get(alsInvocationId);
            if (alsPending && alsPending.msg === completeEvent.msg) {
                return alsInvocationId;
            }
        }
        const nodeId = completeEvent.node && completeEvent.node.id;
        for (const [candidateId, candidate] of this._pending) {
            if (candidate.nodeId === nodeId && candidate.msg === completeEvent.msg) {
                return candidateId;
            }
        }
        return alsInvocationId;
    }

    _onComplete(completeEvent, done) {
        const invocationId = this._resolveInvocationId(completeEvent);
        if (invocationId && this._pending.has(invocationId)) {
            // issue #13: Node-RED's own Complete-node dispatch
            // (`Flow.js#handleComplete`, unmodified upstream code) runs
            // synchronously AFTER this `onComplete` hook's callback
            // returns (see `Node.js#_complete`), not before. Settling
            // synchronously here would delete `pending` before a wired
            // Complete node gets a chance to `receive()` and `send()` its
            // own message, silently dropping that capture. Deferring
            // settlement by one macrotask (`setImmediate`) lets the rest of
            // the CURRENT synchronous call stack - including
            // `handleComplete` - finish first; `AsyncLocalStorage` context
            // still correctly follows the deferred callback back to this
            // exact invocation, so the Complete node's `preRoute` capture
            // (recorded normally via `_onPreRoute`) is included in
            // `pending.sends` by the time we actually settle.
            const settle = () => {
                if (!this._pending.has(invocationId)) {
                    return;
                }
                if (completeEvent.error) {
                    this._settleError(invocationId, completeEvent.node.id, completeEvent.error);
                } else {
                    this._settleResolve(invocationId);
                }
            };
            setImmediate(settle);
        }
        done();
    }

    _onNodeError(logMessage) {
        const invocationId = this._als.getStore();
        if (!invocationId || !this._pending.has(invocationId)) {
            return;
        }
        const pending = this._pending.get(invocationId);
        const error = logMessage instanceof Error ? logMessage : new Error(String(logMessage));
        this._settleError(invocationId, pending.nodeId, error);
    }

    _settleResolve(invocationId) {
        const pending = this._pending.get(invocationId);
        if (!pending) {
            return;
        }
        clearTimeout(pending.timer);
        this._pending.delete(invocationId);
        pending.resolve({ sends: pending.sends });
    }

    _settleError(invocationId, nodeId, error) {
        const pending = this._pending.get(invocationId);
        if (!pending) {
            return;
        }
        clearTimeout(pending.timer);
        this._pending.delete(invocationId);
        pending.reject({ nodeId, error, sends: pending.sends });
    }
}

module.exports = { Capture, DEFAULT_TIMEOUT_MS };
